def fitpoly(cols,deg):
    terms=[]
    for i in range(deg+1):
        for j in range(deg+1-i):
            terms.append(cols[0]**i*cols[1]**j)
    X=np.column_stack(terms)
    c=np.linalg.lstsq(X,s,rcond=None)[0]
    r=s-X@c
